def PermissionCheck(required: Permission)(implicit ec: ExecutionContext) =
  new ActionFilter[UserRequest] {
    def executionContext = ec
    def filter[A](req: UserRequest[A]) = Future.successful {
      if (req.grants.contains(required)) None       // explicit grant -> continue
      else Some(Forbidden)                          // no grant -> stop the request
    }
  }
